export const SCENARIOS: Scenario[] = CATEGORIES.flatMap((c) =>
  c.messages.map((message, i) => ({
    id: `${c.key}-${i + 1}`,
    category: c.key,
    categoryLabel: c.label,
    message,
  })),
);

export const SCENARIO_CATEGORIES = CATEGORIES.map((c) => ({
  key: c.key,
  label: c.label,
  count: c.messages.length,
}));

